package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.level.levelgen.Heightmap;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.pieces.*;import net.minecraftforge.registries.*;import com.mojang.serialization.JsonOps;import net.minecraft.resources.RegistryOps;
public class WGWorldgen {
 public static final DeferredRegister<StructurePieceType> PIECES=DeferredRegister.create(Registries.STRUCTURE_PIECE,"witchinggadgets");public static final RegistryObject<StructurePieceType> PIECE=PIECES.register("photo_workshop",()->PhotoWorkshopPiece::new);
 public static void village(Structure.GenerationContext context,StructurePiecesBuilder builder){if(!context.random().nextBoolean())return;record Site(BlockPos pos,Direction facing){}var sites=new ArrayList<Site>();for(var piece:builder.build().pieces()){if(!(piece instanceof PoolElementStructurePiece pool))continue;var encoded=net.minecraft.world.level.levelgen.structure.pools.StructurePoolElement.CODEC.encodeStart(RegistryOps.create(JsonOps.INSTANCE,context.registryAccess()),pool.getElement()).result();if(encoded.isEmpty()||!encoded.get().toString().contains("/streets/"))continue;var b=piece.getBoundingBox();for(int x=b.minX()+2;x<=b.maxX()-2;x+=4){sites.add(new Site(new BlockPos(x,0,b.minZ()-1),Direction.SOUTH));sites.add(new Site(new BlockPos(x,0,b.maxZ()+1),Direction.NORTH));}for(int z=b.minZ()+2;z<=b.maxZ()-2;z+=4){sites.add(new Site(new BlockPos(b.minX()-1,0,z),Direction.EAST));sites.add(new Site(new BlockPos(b.maxX()+1,0,z),Direction.WEST));}}for(int i=sites.size()-1;i>0;i--)Collections.swap(sites,i,context.random().nextInt(i+1));for(var site:sites){var delta=PhotoWorkshopPiece.rotate(3,0,site.facing());var piece=new PhotoWorkshopPiece(site.pos().offset(-delta.getX(),0,-delta.getZ()),site.facing());var b=piece.getBoundingBox();long height=0;for(int x=b.minX();x<=b.maxX();x++)for(int z=b.minZ();z<=b.maxZ();z++)height+=Math.max(context.chunkGenerator().getSeaLevel(),context.chunkGenerator().getFirstFreeHeight(x,z,Heightmap.Types.WORLD_SURFACE_WG,context.heightAccessor(),context.randomState()));int floor=(int)(height/49);if(floor+10>=context.heightAccessor().getMaxBuildHeight())continue;piece.move(0,floor,0);if(builder.findCollisionPiece(piece.getBoundingBox())==null){builder.addPiece(piece);return;}}}
}
